CHAUFFEUR_JOUR = 7000


def reprendre_les_prix(apps, schema_editor):
    """Anciennes catégories : prix par jour = prix sans chauffeur, sinon prix avec chauffeur moins le chauffeur
    (désormais facturé à part) ; caution convertie en journées (une ou deux), plafonnée à 100 000 FCFA."""
    Vehicule = apps.get_model('locations', 'CategorieVehiculeModel')
    for v in Vehicule.objects.all():
        sans, avec = v.prix_jour_sans_chauffeur, v.prix_jour_avec_chauffeur
        v.prix_jour = sans or (max(avec - CHAUFFEUR_JOUR, 1000) if avec else None)
        # Sans aucun prix (catégories types jamais renseignées) : les deux formules restent proposables
        v.sans_chauffeur, v.avec_chauffeur = (sans is not None, avec is not None) if (sans or avec) else (True, True)
        v.caution_jours = 0 if not v.caution or not v.prix_jour else (1 if v.caution <= v.prix_jour else 2)
        v.caution = min(v.caution_jours * (v.prix_jour or 0), 100_000)
        v.save(update_fields=['prix_jour', 'sans_chauffeur', 'avec_chauffeur', 'caution_jours', 'caution'])


